INSERT IGNORE INTO ai_sales_script
    (id, organization_id, category, title, content, source, create_time, update_time, create_user, update_user)
VALUES
('910000000009000001', @ORG, '价格异议', '价格贵·算账重塑价值', '先认同客户：「这个价格确实不低」。再帮客户算一笔账——把投入摊到每天或每一单，对比它带来的效率提升、人力节省和风险规避，把「贵」翻译成「值」。不要一上来就降价，先谈价值。', '系统示例', @TS, @TS, '910000000003100001', '910000000003100001'),
('910000000009000002', @ORG, '价格异议', '客户要折扣·守住底线换资源', '客户坚持要折扣时，不要轻易降价的数字，而是用等价的资源置换：延长免费运维、送一次培训、优先排期上线。既保住了价格锚点，又让客户觉得拿到了实在好处。', '公司内部整理', @TS, @TS, '910000000003100002', '910000000003100002'),
('910000000009000003', @ORG, '促单逼单', '月底促单·锁定优惠', '本月底前签约可锁定当前折扣与年度价格，下月价格政策可能调整。用「政策节点 + 排期紧张」两个理由给客户明确的行动时间，并当场敲定签约所需材料。', '销售总监分享', @TS, @TS, '910000000003100003', '910000000003100003'),
('910000000009000004', @ORG, '促单逼单', '客户犹豫·给台阶促单', '客户说「再考虑考虑」时，用一个明确的推进理由（限时优惠、阶梯报价、排期资源）给客户一个台阶，并当场约定下次沟通的具体时间，避免无限期拖延。', '系统示例', @TS, @TS, '910000000003100004', '910000000003100004'),
('910000000009000005', @ORG, '竞品对比', '竞品更便宜·聚焦差异', '先肯定客户做过对比：「您对比过，说明您是认真在决策」。再点出我们独有的能力（如权限管理、一键导出、售后服务），说明价格差买来的是这些确定性，而不是泛泛地说「我们更好」。', '系统示例', @TS, @TS, '910000000003100005', '910000000003100005'),
('910000000009000006', @ORG, '开场白', '首次拜访·三句话破冰', '第一句说明来意，第二句说清能帮客户解决的痛点，第三句抛出一个具体问题引导客户开口。控制在 30 秒内，把主场交回给客户。', '公司内部整理', @TS, @TS, '910000000003100001', '910000000003100001');
